// Adapted from ww6 src/services/allocationEngineService.ts:43-104 @ 09751ce (Prisma and money removed):
// rule matching by tag and the run summary the report shows.
export function tagsMatch(key, value, tags) {
  return Object.prototype.hasOwnProperty.call(tags, key) && String(tags[key]) === value;
}

export function computeSummary(costItems, rules) {
  const matched = new Set();
  let unmatchedLineItems = 0;
  for (const item of costItems) {
    const hits = rules.filter((r) => tagsMatch(r.matchTagKey, r.matchTagValue, item.tags ?? {}));
    if (hits.length === 0) unmatchedLineItems += 1;
    for (const r of hits) matched.add(r);
  }
  return {
    evaluatedLineItems: costItems.length,
    matchedRules: matched.size,
    unmatchedLineItems
  };
}

